function transfer(address recipient, uint256 amount) public returns (bool) {
    require(amount <= balanceOf[msg.sender], 'Insufficient balance');
    balanceOf[msg.sender] -= amount;
    balanceOf[recipient] += amount;
    emit Transfer(msg.sender, recipient, amount);
    return true;
}

function transferFrom(address sender, address recipient, uint256 amount) public returns (bool) {
    require(amount <= balanceOf[sender], 'Insufficient balance');
    balanceOf[sender] -= amount;
    balanceOf[recipient] += amount;
    emit Transfer(sender, recipient, amount);
    return true;
}

function mintToken(uint256 amount) public onlyOwner {
    require(amount > 0, 'Amount must be greater than 0');
    balanceOf[owner] += amount;
    emit Transfer(address(0), owner, amount);
}

function buy() public payable {
    uint256 tokens = msg.value * buyRate;
    require(tokens > 0, 'Buy amount must be greater than 0');
    require(balanceOf[owner] >= tokens, 'Insufficient tokens in the contract');
    balanceOf[owner] -= tokens;
    balanceOf[msg.sender] += tokens;
    emit Transfer(owner, msg.sender, tokens);
}
